import csv
from typing import List, Dict, Any, Tuple

def parse_csv(raw_csv: str) -> Tuple[List[str], List[List[str]]]:
    """
    Parses a raw CSV string into a list of headers and rows.

    Parameters:
    raw_csv (str): The complete raw file content

    Returns:
    tuple: (headers, rows) where headers is a list of strings and rows is a list of lists of strings
    """
    if not raw_csv or not isinstance(raw_csv, str):
        return [], []

    # Split by delimiter
    lines = raw_csv.split(',')

    # Handle multi-line headers (detected as such)
    header_lines = []
    current_header = None

    for line in lines:
        if line.strip() == '':
            continue

        if current_header is not None:
            header_lines.append(current_header)
            current_header = None
        else:
            current_header = line.strip()

    # Handle multi-line headers (detected as such)
    if current_header is not None:
        header_lines.append(current_header)

    # Parse headers
    headers = []
    for line in header_lines:
        if line.strip():
            try:
                headers.append(line.strip())
            except ValueError:
                headers.append(line)

    # Parse rows
    rows = []
    current_row = []

    for line in lines:
        if not line.strip():
            continue

        # Check for quoted newlines (detected as such)
        if line.startswith('"') and line.endswith('"'):
            # Extract content between quotes
            start_idx = line[1:-1].index('"')
            content = line[start_idx+1:start_idx+2]

            # Split by delimiter
            parts = content.split(',')

            # Check for malformed widths (detected as such)
            if len(parts) != 2:
                continue

            try:
                values = [p.strip() for p in parts]
                current_row.extend(values)
            except ValueError:
                current_row.append(line)
        else:
            # Check for escaped quotes (detected as such)
            if line.startswith('"') and line.endswith('"'):
                start_idx = line[1:-1].index('"')
                content = line[start_idx+1:start_idx+2]

                # Split by delimiter
                parts = content.split(',')

                # Check for malformed widths (detected as such)
                if len(parts) != 2:
                    continue

                try:
                    values = [p.strip() for p in parts]
                    current_row.extend(values)
                except ValueError:
                    current_row.append(line)
            else:
                # Check for preambles (detected as such)
                if line.startswith('"') and line.endswith('"'):
                    start_idx = line[1:-1].index('"')
                    content = line[start_idx+1:start_idx+2]

                    # Split by delimiter
                    parts = content.split(',')

                    # Check for malformed widths (detected as such)
                    if len(parts) != 2:
                        continue

                    try:
                        values = [p.strip() for p in parts]
                        current_row.extend(values)
                    except ValueError:
                        current_row.append(line)
                else:
                    # Check for preambles (detected as such)
                    if line.startswith('"') and line.endswith('"'):
                        start_idx = line[1:-1].index('"')
                        content = line[start_idx+1:start_idx+2]

                        # Split by delimiter
                        parts = content.split(',')

                        # Check for malformed widths (detected as such)
                        if len(parts) != 2:
                            continue

                        try:
                            values = [p.strip() for p in parts]
                            current_row.extend(values)
                        except ValueError:
                            current_row.append(line)
                    else:
                        # Check for preambles (detected as such)
                        if line.startswith('"') and line.endswith('"'):
                            start_idx = line[1:-1].index('"')
                            content = line[start_idx+1:start_idx+2]

                            # Split by delimiter
                            parts = content.split(',')

                            # Check for malformed widths (detected as such)
                            if len(parts) != 2:
                                continue

                        try:
                            values = [p.strip() for p in parts]
                            current_row.extend(values)
                        except ValueError:
                            current_row.append(line)

    return headers, rows
